begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
('e3e30000-0000-4000-8000-000000000001','photo-a@example.test'),
('e3e30000-0000-4000-8000-000000000002','photo-b@example.test');
select ok(not (select public from storage.buckets where id='project-photos'),'photo bucket private');
select is((select file_size_limit from storage.buckets where id='project-photos'),10485760::bigint,'bucket size bound');
select is((select allowed_mime_types from storage.buckets where id='project-photos'),array['image/webp'],'only normalized WebP accepted');
select ok(not has_table_privilege('authenticated','public.project_photos','INSERT'),'photo metadata not client writable');
select ok(not has_table_privilege('authenticated','public.project_photo_changes','SELECT'),'receipts not client readable');
select ok(not has_table_privilege('authenticated','public.project_photo_changes','INSERT'),'receipts not client writable');
select ok(not has_function_privilege('authenticated','public.begin_project_photo_change(uuid,uuid,uuid,bigint,text,text,text)','EXECUTE'),'client cannot impersonate user through trusted RPC');
select ok(not has_function_privilege('anon','public.commit_project_photo_change(uuid,uuid,uuid,integer,integer,integer)','EXECUTE'),'anonymous commit denied');
select ok(has_function_privilege('service_role','public.commit_project_photo_change(uuid,uuid,uuid,integer,integer,integer)','EXECUTE'),'trusted server can commit');
set local role authenticated;
set local request.jwt.claim.sub='e3e30000-0000-4000-8000-000000000001';
select set_config('test.phproject',public.create_project('e3e30000-0000-4000-8000-000000000010','사진 테스트',null)::text,true);
select set_config('test.pid',current_setting('test.phproject')::jsonb->>'id',true);
select is(public.apply_counter_command('e3e30000-0000-4000-8000-000000000011',(current_setting('test.phproject')::jsonb->>'workItemId')::uuid,0,now(),'photo-test','{"type":"change","counter":"stitch","delta":1}')->>'status','applied','counter prior to cover');
set local role postgres;
select set_config('test.ph1',public.begin_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000012',0,'upload',repeat('a',64),repeat('b',64))::text,true);
select is((select cover_photo_id from public.projects where id=current_setting('test.pid')::uuid),null::uuid,'reservation does not change cover');
select throws_ok(format('insert into public.project_photos(project_id,user_id,object_path,content_hash) values(%L,%L,%L,%L)',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000002','wrong-path',repeat('a',64)),'23514',null,'object path cannot be forged');
select throws_ok(format('update public.project_photos set user_id=%L,object_path=%L||project_id::text||%L||id::text||%L where id=%L','e3e30000-0000-4000-8000-000000000002','e3e30000-0000-4000-8000-000000000002/','/','.webp',current_setting('test.ph1')::jsonb->>'photoId'),'23503',null,'photo owner must match project owner');

select is((select revision from public.projects where id=current_setting('test.pid')::uuid),0::bigint,'reservation does not increment revision');
select is(public.begin_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000012',0,'upload',repeat('a',64),repeat('b',64))->>'photoId',current_setting('test.ph1')::jsonb->>'photoId','pending retry reuses candidate');
select throws_ok(format('select public.commit_project_photo_change(%L,%L,%L,80,40,100)','e3e30000-0000-4000-8000-000000000001',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000012'),'23514',null,'missing Storage object cannot be attached');
insert into storage.objects(bucket_id,name) values('project-photos',current_setting('test.ph1')::jsonb->>'path');
select throws_ok(format('select public.commit_project_photo_change(%L,%L,%L,1601,40,100)','e3e30000-0000-4000-8000-000000000001',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000012'),'23514',null,'dimensions bounded');
select throws_ok(format('select public.commit_project_photo_change(%L,%L,%L,80,40,0)','e3e30000-0000-4000-8000-000000000001',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000012'),'23514',null,'empty optimized file cannot be attached');
select is(public.commit_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000012',80,40,100)->>'status','committed','cover commit');
select is((select revision from public.projects where id=current_setting('test.pid')::uuid),1::bigint,'cover increments shared project revision');
select is(public.commit_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000012')->>'duplicate','true','lost commit response retry idempotent');
select throws_ok(format('select public.begin_project_photo_change(%L,%L,%L,0,%L,%L,%L)','e3e30000-0000-4000-8000-000000000001',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000012','upload',repeat('f',64),repeat('b',64)),'22023',null,'same request cannot change bytes');
select throws_ok(format('select public.begin_project_photo_change(%L,%L,%L,1,%L,null,null)','e3e30000-0000-4000-8000-000000000002',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000012','delete'),'P0002',null,'wrong owner denied even on trusted function');
set local role authenticated;
select is((select count(*) from public.project_photos),1::bigint,'owner reads only current photo');
select is((select count(*) from storage.objects where bucket_id='project-photos'),1::bigint,'owner reads current Storage object');
select throws_ok(format('insert into storage.objects(bucket_id,name) values(%L,%L)','project-photos','e3e30000-0000-4000-8000-000000000001/forged.webp'),'42501',null,'direct Storage upload bypass denied');
select throws_ok($$delete from storage.objects where bucket_id='project-photos'$$,null,null,'direct Storage SQL delete blocked');
select is((select count(*) from storage.objects where bucket_id='project-photos'),1::bigint,'direct Storage delete cannot remove current object');
set local request.jwt.claim.sub='e3e30000-0000-4000-8000-000000000002';
select is((select count(*) from public.project_photos),0::bigint,'other user cannot see photo metadata');
select is((select count(*) from storage.objects where bucket_id='project-photos'),0::bigint,'other user cannot read private object');
set local role postgres;
select set_config('test.ph2',public.begin_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000013',1,'upload',repeat('c',64),repeat('d',64))::text,true);
select set_config('test.ph3',public.begin_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000014',1,'upload',repeat('e',64),repeat('f',64))::text,true);
select is((select cover_photo_id::text from public.projects where id=current_setting('test.pid')::uuid),current_setting('test.ph1')::jsonb->>'photoId','old photo kept throughout staging');
insert into storage.objects(bucket_id,name) values('project-photos',current_setting('test.ph2')::jsonb->>'path');
select is(public.commit_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000013',80,40,100)->>'revision','2','replacement committed');
select throws_ok(format('select public.commit_project_photo_change(%L,%L,%L,80,40,100)','e3e30000-0000-4000-8000-000000000001',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000014'),'40001',null,'competing revision cannot overwrite');
select is((select cover_photo_id::text from public.projects where id=current_setting('test.pid')::uuid),current_setting('test.ph2')::jsonb->>'photoId','winner retained after conflict');
select is(jsonb_array_length(public.project_photo_cleanup_candidates('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid)),1,'only retired old image eligible for cleanup');
select is((select count(*) from storage.objects where bucket_id='project-photos' and name in (current_setting('test.ph1')::jsonb->>'path',current_setting('test.ph2')::jsonb->>'path')),2::bigint,'DB commit never directly deletes fixture Storage objects');
select is(public.begin_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000012',0,'upload',repeat('a',64),repeat('b',64))->>'duplicate','true','old confirmed request remains idempotent at new revision');
select public.abandon_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000014');
select is((select status from public.project_photo_changes where request_id='e3e30000-0000-4000-8000-000000000014'),'abandoned','failed candidate can be abandoned');
select is(jsonb_array_length(public.project_photo_cleanup_candidates('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid)),1,'fresh staged candidate waits for in-flight upload grace');
select public.confirm_project_photo_cleanup('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,(current_setting('test.ph2')::jsonb->>'photoId')::uuid);
select is((select cleaned_at from public.project_photos where id=(current_setting('test.ph2')::jsonb->>'photoId')::uuid),null::timestamptz,'current photo never marked cleaned');
set local role authenticated;
set local request.jwt.claim.sub='e3e30000-0000-4000-8000-000000000001';
select is((select count(*) from public.project_photos),1::bigint,'retired and staged metadata hidden');
select is((select count(*) from storage.objects where bucket_id='project-photos'),1::bigint,'retired object no longer client readable');
set local role anon;
select is((select count(*) from storage.objects where bucket_id='project-photos'),0::bigint,'anonymous Storage read denied');
select throws_ok('select * from public.project_photos','42501',null,'anonymous metadata read denied');
set local role authenticated;

select is(public.delete_project(current_setting('test.pid')::uuid,2)->>'result','deleted','soft delete project');
select is((select count(*) from public.project_photos),0::bigint,'deleted project photo access blocked');
select is((select count(*) from storage.objects where bucket_id='project-photos'),0::bigint,'deleted project private object access blocked');
set local role postgres;
select is((select cover_photo_id::text from public.projects where id=current_setting('test.pid')::uuid),current_setting('test.ph2')::jsonb->>'photoId','soft deletion preserves photo reference');
select throws_ok(format('select public.begin_project_photo_change(%L,%L,%L,3,%L,null,null)','e3e30000-0000-4000-8000-000000000001',current_setting('test.pid'),'e3e30000-0000-4000-8000-000000000015','delete'),'P0002',null,'deleted project cannot change photo');
set local role authenticated;
select is(public.restore_project(current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000016',3)->>'status','restored','restore project');
select is((select id::text from public.project_photos),current_setting('test.ph2')::jsonb->>'photoId','same photo restored');
select is((select current_value from public.counters where work_item_id=(current_setting('test.phproject')::jsonb->>'workItemId')::uuid and counter_type='stitch'),1::bigint,'counter value preserved');
select is((select count(*) from public.counter_events where work_item_id=(current_setting('test.phproject')::jsonb->>'workItemId')::uuid),1::bigint,'counter event preserved');
set local role postgres;
select public.begin_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000017',4,'delete');
select is(public.commit_project_photo_change('e3e30000-0000-4000-8000-000000000001',current_setting('test.pid')::uuid,'e3e30000-0000-4000-8000-000000000017')->>'status','committed','delete pointer confirmed');
select is((select cover_photo_id from public.projects where id=current_setting('test.pid')::uuid),null::uuid,'delete yields placeholder');
select is((select count(*) from public.project_parts where project_id=current_setting('test.pid')::uuid),1::bigint,'photo delete does not delete project parts');
select * from finish();
rollback;
